# Apartats 6.6-6.8 (percentatges, càlcul del tant per cent i del total, augments i disminucions) dels apunts de la
# Unitat 6 de 2n ESO. Les asserts ck() comproven els resultats escrits a mà.
from comu import *

def pctw(wid, m, p, n, a, qs):
    return (f'<div class="widget w-pctc" id="{wid}">\n  <div class="wt">💯 {L("Calculadora de percentatges", "Calculadora de porcentajes", "Percentage calculator")}</div>\n'
            + f'  <div class="wrow">{gseg("m", [("a", L("Calcula la part", "Calcula la parte", "Find the part")), ("p", L("Calcula el %", "Calcula el %", "Find the %")), ("n", L("Calcula el total", "Calcula el total", "Find the whole"))], m)}</div>\n'
            + f'  <div class="wrow" style="margin-top:8px">{nin("p", "Percentatge (%)", "Porcentaje (%)", "Percentage (%)", p, "s")}{nin("n", "Total", "Total", "Whole", n, "s")}{nin("a", "Part", "Parte", "Part", a, "s")}</div>\n'
            + '  ' + quick(qs) + '\n  <div class="fvis"></div>\n  <div class="info" aria-live="polite"></div>\n</div>\n')

# ============================================================ 6.6
PE = [('50', r'\frac{1}{2}', r'0\dc5', 'la meitat', 'la mitad', 'half'), ('25', r'\frac{1}{4}', r'0\dc25', 'la quarta part', 'la cuarta parte', 'a quarter'),
      ('75', r'\frac{3}{4}', r'0\dc75', 'tres quartes parts', 'tres cuartas partes', 'three quarters'), ('20', r'\frac{1}{5}', r'0\dc2', 'la cinquena part', 'la quinta parte', 'a fifth'),
      ('10', r'\frac{1}{10}', r'0\dc1', 'la desena part', 'la décima parte', 'a tenth'), ('5', r'\frac{1}{20}', r'0\dc05', 'la meitat del 10 %', 'la mitad del 10 %', 'half of 10%'),
      ('1', r'\frac{1}{100}', r'0\dc01', 'la centèsima part', 'la centésima parte', 'a hundredth'), ('100', '1', '1', 'el total', 'el total', 'the whole'),
      ('150', r'\frac{3}{2}', r'1\dc5', 'el total i la meitat', 'el total y la mitad', 'one and a half times')]
s6 = box('def', L('Què és un percentatge?', '¿Qué es un porcentaje?', 'What is a percentage?'),
  P(r"Un <strong>percentatge</strong> o <strong>tant per cent</strong> és una raó amb denominador 100. El 35 % (es llig «35 per cent») vol dir <strong>35 de cada 100</strong>. Es pot escriure com a fracció o com a nombre decimal:",
    r"Un <strong>porcentaje</strong> o <strong>tanto por ciento</strong> es una razón con denominador 100. El 35 % (se lee «35 por ciento») quiere decir <strong>35 de cada 100</strong>. Se puede escribir como fracción o como número decimal:",
    r"A <strong>percentage</strong> is a ratio with denominator 100. 35% (read “35 percent”) means <strong>35 out of every 100</strong>. It can be written as a fraction or as a decimal number:")
  + r'\[35\,\%=\frac{35}{100}=\frac{7}{20}=0\dc35\]'
  + figs((pgrid(35), r'\(35\,\%\)'))
  + P(r"Per a passar un percentatge a decimal, el dividim entre 100 (movem la coma dos llocs a l'esquerra): \(8\,\%=0\dc08\), \(\ 12\dc5\,\%=0\dc125\), \(\ 130\,\%=1\dc3\). I al revés, un decimal o una fracció es passen a percentatge multiplicant per 100: \(0\dc4=40\,\%\), \(\ \frac{3}{8}=0\dc375=37\dc5\,\%\).",
      r"Para pasar un porcentaje a decimal, lo dividimos entre 100 (movemos la coma dos lugares a la izquierda): \(8\,\%=0\dc08\), \(\ 12\dc5\,\%=0\dc125\), \(\ 130\,\%=1\dc3\). Y al revés, un decimal o una fracción se pasan a porcentaje multiplicando por 100: \(0\dc4=40\,\%\), \(\ \frac{3}{8}=0\dc375=37\dc5\,\%\).",
      r"To turn a percentage into a decimal, divide it by 100 (move the point two places left): \(8\%=0\dc08\), \(\ 12\dc5\%=0\dc125\), \(\ 130\%=1\dc3\). The other way round, a decimal or a fraction becomes a percentage by multiplying by 100: \(0\dc4=40\%\), \(\ \frac{3}{8}=0\dc375=37\dc5\%\).")
  + table([L('Percentatge', 'Porcentaje', 'Percentage'), L('Fracció', 'Fracción', 'Fraction'), L('Decimal', 'Decimal', 'Decimal'), L('Vol dir…', 'Quiere decir…', 'Means…')],
          [[r'\(%s\,\%%\)' % p, r'\(%s\)' % f, r'\(%s\)' % d, L(va, es, en)] for p, f, d, va, es, en in PE]))
ck(Fr(35, 100), Fr(7, 20)); ck(Fr(3, 8), Dm('0.375'))
s6 += box('prop', L("Calcular el percentatge d'una quantitat", 'Calcular el porcentaje de una cantidad', 'Finding a percentage of an amount'),
  P(r"Hi ha tres maneres equivalents de calcular el \(p\,\%\) d'una quantitat \(C\):", r"Hay tres maneras equivalentes de calcular el \(p\,\%\) de una cantidad \(C\):", r"There are three equivalent ways to find \(p\%\) of an amount \(C\):")
  + ol(L(r"<strong>Amb el decimal:</strong> multipliquem la quantitat pel percentatge en forma decimal: \(\ 35\,\%\ \text{de}\ 80=80\cdot0\dc35=\boxed{28}\).", r"<strong>Con el decimal:</strong> multiplicamos la cantidad por el porcentaje en forma decimal: \(\ 35\,\%\ \text{de}\ 80=80\cdot0\dc35=\boxed{28}\).", r"<strong>With the decimal:</strong> multiply the amount by the percentage as a decimal: \(\ 35\%\ \text{of}\ 80=80\cdot0\dc35=\boxed{28}\)."),
       L(r"<strong>Amb la fracció:</strong> multipliquem pel percentatge i dividim entre 100: \(\ \frac{35\cdot80}{100}=\frac{2800}{100}=28\).", r"<strong>Con la fracción:</strong> multiplicamos por el porcentaje y dividimos entre 100: \(\ \frac{35\cdot80}{100}=\frac{2800}{100}=28\).", r"<strong>With the fraction:</strong> multiply by the percentage and divide by 100: \(\ \frac{35\cdot80}{100}=\frac{2800}{100}=28\)."),
       L(r"<strong>Amb una regla de tres directa:</strong> si de 100 en prenem 35, de 80 en prenem \(x\):", r"<strong>Con una regla de tres directa:</strong> si de 100 tomamos 35, de 80 tomamos \(x\):", r"<strong>With a direct rule of three:</strong> if out of 100 we take 35, out of 80 we take \(x\):"))
  + r3('100', r'\tri{total}{total}{whole}', '35', r'\tri{part}{parte}{part}', '80', r'\tri{total}{total}{whole}') + r'\[x=\frac{35\cdot80}{100}=28\]')
ck(80 * Dm('0.35'), 28)
s6 += box('prop', L('Càlcul mental de percentatges', 'Cálculo mental de porcentajes', 'Working out percentages in your head'),
  ul(L(r"El <strong>10 %</strong> és dividir entre 10: el 10 % de 340 és 34.", r"El <strong>10 %</strong> es dividir entre 10: el 10 % de 340 es 34.", r"<strong>10%</strong> means dividing by 10: 10% of 340 is 34."),
     L(r"El <strong>5 %</strong> és la meitat del 10 %: el 5 % de 340 és 17.", r"El <strong>5 %</strong> es la mitad del 10 %: el 5 % de 340 es 17.", r"<strong>5%</strong> is half of 10%: 5% of 340 is 17."),
     L(r"El <strong>50 %</strong> és la meitat; el <strong>25 %</strong>, la quarta part; el <strong>20 %</strong>, la cinquena part; el <strong>1 %</strong>, dividir entre 100.", r"El <strong>50 %</strong> es la mitad; el <strong>25 %</strong>, la cuarta parte; el <strong>20 %</strong>, la quinta parte; el <strong>1 %</strong>, dividir entre 100.", r"<strong>50%</strong> is half; <strong>25%</strong>, a quarter; <strong>20%</strong>, a fifth; <strong>1%</strong>, dividing by 100."),
     L(r"Combinant-los: el 15 % de 340 és el 10 % + el 5 % \(=34+17=51\); el 30 % és 3 vegades el 10 % \(=102\).", r"Combinándolos: el 15 % de 340 es el 10 % + el 5 % \(=34+17=51\); el 30 % es 3 veces el 10 % \(=102\).", r"Combining them: 15% of 340 is 10% + 5% \(=34+17=51\); 30% is 3 times 10% \(=102\).")))
ck(340 * Dm('0.15'), 51); ck(340 * Dm('0.3'), 102)
s6 += pctw('w-pct', 'a', '35', '80', '28', [('a;35;80', '35 % de 80'), ('a;15;340', '15 % de 340'), ('a;12,5;64', '12,5 % de 64'), ('a;4;2350', '4 % de 2350'), ('a;120;45', '120 % de 45'), ('a;0,5;3000', '0,5 % de 3000')])
s6 += drill('pof', "Entrena: el tant per cent d'una quantitat", 'Entrena: el tanto por ciento de una cantidad', 'Train: a percentage of an amount')
s6 += level(1, 1,
  prob(L(r"Escriu com a fracció irreductible i com a decimal: a) \(60\,\%\) &nbsp; b) \(4\,\%\) &nbsp; c) \(125\,\%\). Calcula: d) el \(30\,\%\) de 250 &nbsp; e) el \(5\,\%\) de 86 &nbsp; f) el \(75\,\%\) de 48",
         r"Escribe como fracción irreducible y como decimal: a) \(60\,\%\) &nbsp; b) \(4\,\%\) &nbsp; c) \(125\,\%\). Calcula: d) el \(30\,\%\) de 250 &nbsp; e) el \(5\,\%\) de 86 &nbsp; f) el \(75\,\%\) de 48",
         r"Write as a fraction in simplest form and as a decimal: a) \(60\%\) &nbsp; b) \(4\%\) &nbsp; c) \(125\%\). Work out: d) \(30\%\) of 250 &nbsp; e) \(5\%\) of 86 &nbsp; f) \(75\%\) of 48"),
       r'\[\text{a) }\frac{60}{100}=\frac{3}{5}=0\dc6\qquad\text{b) }\frac{4}{100}=\frac{1}{25}=0\dc04\qquad\text{c) }\frac{125}{100}=\frac{5}{4}=1\dc25\]',
       r'\[\text{d) }250\cdot0\dc3=\boxed{75}\qquad\text{e) }86\cdot0\dc05=\boxed{4\dc3}\qquad\text{f) }\frac{3}{4}\cdot48=\boxed{36}\]'))
ck(Fr(60, 100), Fr(3, 5)); ck(Fr(4, 100), Fr(1, 25)); ck(Fr(125, 100), Fr(5, 4)); ck(250 * Dm('0.3'), 75); ck(86 * Dm('0.05'), '4.3'); ck(48 * Dm('0.75'), 36)
s6 += level(2, 2,
  prob(L(r"Un institut té 720 alumnes. El 45 % són xiques, el 15 % ve en bicicleta i el \(2\dc5\,\%\) participa en el consell escolar. Quants alumnes hi ha de cada grup?", r"Un instituto tiene 720 alumnos. El 45 % son chicas, el 15 % viene en bicicleta y el \(2\dc5\,\%\) participa en el consejo escolar. ¿Cuántos alumnos hay de cada grupo?", r"A secondary school has 720 students. 45% are girls, 15% come by bike and \(2\dc5\%\) are on the school council. How many students are in each group?"),
       r'\[720\cdot0\dc45=\boxed{324}\qquad 720\cdot0\dc15=\boxed{108}\qquad 720\cdot0\dc025=\boxed{18}\]',
       P(r"Mentalment: el 10 % és 72 i el 5 % és 36, així que el 15 % és \(72+36=108\).", r"Mentalmente: el 10 % es 72 y el 5 % es 36, así que el 15 % es \(72+36=108\).", r"In your head: 10% is 72 and 5% is 36, so 15% is \(72+36=108\).")))
ck(720 * Dm('0.45'), 324); ck(720 * Dm('0.15'), 108); ck(720 * Dm('0.025'), 18)
s6 += level(3, 3,
  prob(L(r"Un camp de 2400 m² es divideix així: el 40 % per a hortalisses, el 35 % del que queda per a arbres fruiters i la resta per a flors. Quants m² hi ha de cada cultiu? Quin percentatge del camp ocupen les flors?", r"Un campo de 2400 m² se divide así: el 40 % para hortalizas, el 35 % de lo que queda para árboles frutales y el resto para flores. ¿Cuántos m² hay de cada cultivo? ¿Qué porcentaje del campo ocupan las flores?", r"A 2400 m² field is divided like this: 40% for vegetables, 35% of what's left for fruit trees and the rest for flowers. How many m² of each crop are there? What percentage of the field do the flowers take up?"),
       r'\[\tri{Hortalisses}{Hortalizas}{Vegetables}:\ 2400\cdot0\dc4=\boxed{960\ \text{m}^2}\qquad\tri{Queden}{Quedan}{Left}:\ 2400-960=1440\ \text{m}^2\]',
       r'\[\tri{Fruiters}{Frutales}{Fruit trees}:\ 1440\cdot0\dc35=\boxed{504\ \text{m}^2}\qquad\tri{Flors}{Flores}{Flowers}:\ 1440-504=\boxed{936\ \text{m}^2}\]',
       P(r"Les flors ocupen \(\frac{936}{2400}=0\dc39=\boxed{39\,\%}\) del camp. Compte: els fruiters no són el 35 % del camp, sinó el 35 % del 60 %, és a dir, el 21 %.", r"Las flores ocupan \(\frac{936}{2400}=0\dc39=\boxed{39\,\%}\) del campo. Cuidado: los frutales no son el 35 % del campo, sino el 35 % del 60 %, es decir, el 21 %.", r"The flowers take up \(\frac{936}{2400}=0\dc39=\boxed{39\%}\) of the field. Careful: the fruit trees aren't 35% of the field but 35% of 60%, that is, 21%.")))
ck(2400 * Dm('0.4'), 960); ck(1440 * Dm('0.35'), 504); ck(Dm(936) / 2400, '0.39'); ck(Dm('0.35') * Dm('0.6'), '0.21')
s6 += practice([
  ('★', L(r"a) Calcula mentalment el 10 %, el 5 %, el 50 % i el 25 % de 260. b) Escriu en forma de percentatge: \(0\dc07\), \(\ 0\dc7\), \(\ \frac{9}{20}\), \(\ 1\dc4\).", r"a) Calcula mentalmente el 10 %, el 5 %, el 50 % y el 25 % de 260. b) Escribe en forma de porcentaje: \(0\dc07\), \(\ 0\dc7\), \(\ \frac{9}{20}\), \(\ 1\dc4\).", r"a) Work out in your head 10%, 5%, 50% and 25% of 260. b) Write as percentages: \(0\dc07\), \(\ 0\dc7\), \(\ \frac{9}{20}\), \(\ 1\dc4\).")),
  ('★★', L(r"c) El 21 % de 140 €. d) L'aire conté un 21 % d'oxigen. Quants litres d'oxigen hi ha en una aula de 180 000 L d'aire? e) El \(0\dc8\,\%\) de 4500.", r"c) El 21 % de 140 €. d) El aire contiene un 21 % de oxígeno. ¿Cuántos litros de oxígeno hay en un aula de 180 000 L de aire? e) El \(0\dc8\,\%\) de 4500.", r"c) 21% of 140 €. d) Air is 21% oxygen. How many litres of oxygen are there in a classroom with 180,000 L of air? e) \(0\dc8\%\) of 4500.")),
  ('★★★', L(r"f) Què és més, el 20 % del 30 % de 500 o el 30 % del 20 % de 500? g) En una classe de 25 alumnes, el 40 % ha aprovat totes les matèries i, d'aquests, el 30 % té excel·lent en Matemàtiques. Quants alumnes tenen excel·lent?", r"f) ¿Qué es más, el 20 % del 30 % de 500 o el 30 % del 20 % de 500? g) En una clase de 25 alumnos, el 40 % ha aprobado todas las materias y, de estos, el 30 % tiene sobresaliente en Matemáticas. ¿Cuántos alumnos tienen sobresaliente?", r"f) Which is more, 20% of 30% of 500 or 30% of 20% of 500? g) In a class of 25, 40% have passed every subject and, of those, 30% have top marks in Maths. How many students have top marks?"))],
  P(r"a) 26, 13, 130 i 65. &nbsp; b) \(7\,\%\), \(70\,\%\), \(45\,\%\) i \(140\,\%\).", r"a) 26, 13, 130 y 65. &nbsp; b) \(7\,\%\), \(70\,\%\), \(45\,\%\) y \(140\,\%\).", r"a) 26, 13, 130 and 65. &nbsp; b) \(7\%\), \(70\%\), \(45\%\) and \(140\%\).")
  + P(r"c) \(140\cdot0\dc21=29\dc40\) €. &nbsp; d) \(180\,000\cdot0\dc21=37\,800\) L. &nbsp; e) \(4500\cdot0\dc008=36\).", r"c) \(140\cdot0\dc21=29\dc40\) €. &nbsp; d) \(180\,000\cdot0\dc21=37\,800\) L. &nbsp; e) \(4500\cdot0\dc008=36\).", r"c) \(140\cdot0\dc21=29\dc40\) €. &nbsp; d) \(180\,000\cdot0\dc21=37\,800\) L. &nbsp; e) \(4500\cdot0\dc008=36\).")
  + P(r"f) Són iguals: \(500\cdot0\dc3\cdot0\dc2=500\cdot0\dc2\cdot0\dc3=30\). &nbsp; g) \(25\cdot0\dc4=10\) aproven tot; \(10\cdot0\dc3=3\) alumnes.", r"f) Son iguales: \(500\cdot0\dc3\cdot0\dc2=500\cdot0\dc2\cdot0\dc3=30\). &nbsp; g) \(25\cdot0\dc4=10\) aprueban todo; \(10\cdot0\dc3=3\) alumnos.", r"f) They're equal: \(500\cdot0\dc3\cdot0\dc2=500\cdot0\dc2\cdot0\dc3=30\). &nbsp; g) \(25\cdot0\dc4=10\) pass everything; \(10\cdot0\dc3=3\) students."))
ck(260 * Dm('0.25'), 65); ck(Fr(9, 20), Dm('0.45')); ck(140 * Dm('0.21'), '29.4'); ck(180000 * Dm('0.21'), 37800); ck(4500 * Dm('0.008'), 36); ck(500 * Dm('0.06'), 30); ck(25 * Dm('0.4') * Dm('0.3'), 3)

# ============================================================ 6.7
s7 = box('prop', L('Quin tant per cent representa una part respecte del total?', '¿Qué tanto por ciento representa una parte respecto del total?', 'What percentage of the whole is a part?'),
  P(r"Si coneixem el <strong>total</strong> i la <strong>part</strong>, el percentatge és la raó part/total multiplicada per 100:", r"Si conocemos el <strong>total</strong> y la <strong>parte</strong>, el porcentaje es la razón parte/total multiplicada por 100:", r"If we know the <strong>whole</strong> and the <strong>part</strong>, the percentage is the ratio part/whole multiplied by 100:")
  + r'\[p\,\%=\frac{\tri{part}{parte}{part}}{\tri{total}{total}{whole}}\cdot100\]'
  + P(r"<strong>Exemple:</strong> en un examen de 40 preguntes n'encertem 34. Quin percentatge hem encertat?", r"<strong>Ejemplo:</strong> en un examen de 40 preguntas acertamos 34. ¿Qué porcentaje hemos acertado?", r"<strong>Example:</strong> in a 40-question test we get 34 right. What percentage did we get right?")
  + r'\[\frac{34}{40}=0\dc85\ \Rightarrow\ 0\dc85\cdot100=\boxed{85\,\%}\]'
  + P(r"També amb una regla de tres directa: si de 40 n'encertem 34, de 100 n'encertaríem \(x\):", r"También con una regla de tres directa: si de 40 acertamos 34, de 100 acertaríamos \(x\):", r"Also with a direct rule of three: if out of 40 we get 34, out of 100 we'd get \(x\):")
  + r3('40', r'\tri{preguntes}{preguntas}{questions}', '34', r'\tri{encerts}{aciertos}{right}', '100', r'\tri{preguntes}{preguntas}{questions}') + r'\[x=\frac{34\cdot100}{40}=85\ \Rightarrow\ 85\,\%\]'
  + note(r"Compte amb l'ordre: és la <strong>part</strong> dividida entre el <strong>total</strong> (el «de qui» calculem el percentatge). Si eixen més del 100 %, la «part» és més gran que el total.", r"Cuidado con el orden: es la <strong>parte</strong> dividida entre el <strong>total</strong> (el «de quién» calculamos el porcentaje). Si sale más del 100 %, la «parte» es mayor que el total.", r"Watch the order: it's the <strong>part</strong> divided by the <strong>whole</strong> (what we're taking the percentage “of”). If you get more than 100%, the “part” is bigger than the whole.", '⚠️'))
ck(Dm(34) / 40, '0.85')
s7 += box('prop', L('Calcular el total coneixent la part i el percentatge', 'Calcular el total conociendo la parte y el porcentaje', 'Finding the whole from the part and the percentage'),
  P(r"Si sabem quina part és un \(p\,\%\) del total, fem l'operació inversa: <strong>dividim</strong> la part entre el percentatge en forma decimal.", r"Si sabemos qué parte es un \(p\,\%\) del total, hacemos la operación inversa: <strong>dividimos</strong> la parte entre el porcentaje en forma decimal.", r"If we know a part is \(p\%\) of the whole, we do the inverse: <strong>divide</strong> the part by the percentage as a decimal.")
  + r'\[\tri{part}{parte}{part}=\tri{total}{total}{whole}\cdot\frac{p}{100}\qquad\Longrightarrow\qquad\tri{total}{total}{whole}=\tri{part}{parte}{part}:\frac{p}{100}\]'
  + P(r"<strong>Exemple:</strong> 18 alumnes d'un curs, que són el 24 %, han anat a l'excursió. Quants alumnes hi ha en el curs?", r"<strong>Ejemplo:</strong> 18 alumnos de un curso, que son el 24 %, han ido a la excursión. ¿Cuántos alumnos hay en el curso?", r"<strong>Example:</strong> 18 students in a year group, which is 24%, went on the trip. How many students are in the year group?")
  + r'\[\tri{Total}{Total}{Whole}=18:0\dc24=\boxed{75\ \tri{alumnes}{alumnos}{students}}\qquad(\tri{comprovació}{comprobación}{check}:\ 75\cdot0\dc24=18\ ✓)\]'
  + P(r"Amb una regla de tres: si el 24 % són 18 alumnes, el 100 % són \(x=\frac{18\cdot100}{24}=75\).", r"Con una regla de tres: si el 24 % son 18 alumnos, el 100 % son \(x=\frac{18\cdot100}{24}=75\).", r"With a rule of three: if 24% is 18 students, 100% is \(x=\frac{18\cdot100}{24}=75\)."))
ck(Dm(18) / Dm('0.24'), 75)
s7 += pctw('w-pct2', 'p', '', '40', '34', [('p;;40;34', '34 de 40'), ('p;;25;7', '7 de 25'), ('p;;650;91', '91 de 650'), ('p;;80;100', '100 de 80'), ('n;24;;18', '18 → 24 %'), ('n;15;;63', '63 → 15 %'), ('n;2,5;;12', '12 → 2,5 %')])
s7 += drill('pwh', 'Entrena: quin percentatge és?', 'Entrena: ¿qué porcentaje es?', 'Train: what percentage is it?')
s7 += drill('ptot', 'Entrena: calcula el total', 'Entrena: calcula el total', 'Train: find the whole')
s7 += level(1, 1,
  prob(L(r"a) En un poble de 1250 habitants, 350 són menors de 18 anys. Quin percentatge representen? b) El 30 % d'una quantitat és 45. Quina és la quantitat?", r"a) En un pueblo de 1250 habitantes, 350 son menores de 18 años. ¿Qué porcentaje representan? b) El 30 % de una cantidad es 45. ¿Cuál es la cantidad?", r"a) In a village of 1250 people, 350 are under 18. What percentage is that? b) 30% of an amount is 45. What is the amount?"),
       r'\[\text{a) }\frac{350}{1250}=0\dc28=\boxed{28\,\%}\qquad\text{b) }45:0\dc3=\boxed{150}\]'))
