s7 += level(3, 3,
  prob(L(r"Hem pagat 120 € d'entrada per un patinet elèctric, que són el 32 % del preu. a) Quant costa el patinet? b) La resta la paguem en 6 mesos, a parts iguals. Quant paguem cada mes? c) Quin percentatge del preu paguem cada mes?", r"Hemos pagado 120 € de entrada por un patinete eléctrico, que son el 32 % del precio. a) ¿Cuánto cuesta el patinete? b) El resto lo pagamos en 6 meses, a partes iguales. ¿Cuánto pagamos cada mes? c) ¿Qué porcentaje del precio pagamos cada mes?", r"We paid a 120 € deposit on an electric scooter, which is 32% of the price. a) How much does the scooter cost? b) We pay the rest in 6 equal monthly instalments. How much is each? c) What percentage of the price do we pay each month?"),
       r'\[\text{a) }120:0\dc32=\boxed{375\ €}\qquad\text{b) }(375-120):6=255:6=\boxed{42\dc50\ €}\]',
       r'\[\text{c) }\frac{42\dc50}{375}=0\dc1133\ldots\approx\boxed{11\dc33\,\%}\qquad\Big(\tri{o bé}{o bien}{or}\ \ \frac{100-32}{6}=\frac{68}{6}\approx11\dc33\,\%\Big)\]'))
ck(Dm(120) / Dm('0.32'), 375); ck(Dm(255) / 6, '42.5'); ck(round(Fr(4250, 375), 2), Dm('11.33'))
s7 += practice([
  ('★', L(r"a) Quin percentatge representa 18 de 72? I 9 de 12? b) El 25 % d'un nombre és 32. Quin és el nombre?", r"a) ¿Qué porcentaje representa 18 de 72? ¿Y 9 de 12? b) El 25 % de un número es 32. ¿Cuál es el número?", r"a) What percentage of 72 is 18? And 9 of 12? b) 25% of a number is 32. What is the number?")),
  ('★★', L(r"c) En un partit, una jugadora ha llançat 24 tirs lliures i n'ha encertat 21. Quin percentatge d'encert té? d) Un dipòsit conté 330 L, que són el 55 % de la seua capacitat. Quina és la capacitat del dipòsit?", r"c) En un partido, una jugadora ha lanzado 24 tiros libres y ha acertado 21. ¿Qué porcentaje de acierto tiene? d) Un depósito contiene 330 L, que son el 55 % de su capacidad. ¿Cuál es la capacidad del depósito?", r"c) In a match, a player took 24 free throws and scored 21. What is her success rate? d) A tank holds 330 L, which is 55% of its capacity. What is the tank's capacity?")),
  ('★★★', L(r"e) El 12 % dels alumnes d'un institut fan batxillerat d'arts, i són 54 alumnes. Quants alumnes té l'institut? Quants no fan arts? f) Un llibre té 320 pàgines. Si n'hem llegit 136, quin percentatge ens queda per llegir?", r"e) El 12 % de los alumnos de un instituto hacen bachillerato de artes, y son 54 alumnos. ¿Cuántos alumnos tiene el instituto? ¿Cuántos no hacen artes? f) Un libro tiene 320 páginas. Si hemos leído 136, ¿qué porcentaje nos queda por leer?", r"e) 12% of a school's students do the arts baccalaureate, and that's 54 students. How many students does the school have? How many don't do arts? f) A book has 320 pages. If we've read 136, what percentage is left to read?"))],
  P(r"a) \(\frac{18}{72}=25\,\%\); \(\ \frac{9}{12}=75\,\%\). &nbsp; b) \(32:0\dc25=128\).", r"a) \(\frac{18}{72}=25\,\%\); \(\ \frac{9}{12}=75\,\%\). &nbsp; b) \(32:0\dc25=128\).", r"a) \(\frac{18}{72}=25\%\); \(\ \frac{9}{12}=75\%\). &nbsp; b) \(32:0\dc25=128\).")
  + P(r"c) \(\frac{21}{24}=0\dc875=87\dc5\,\%\). &nbsp; d) \(330:0\dc55=600\) L.", r"c) \(\frac{21}{24}=0\dc875=87\dc5\,\%\). &nbsp; d) \(330:0\dc55=600\) L.", r"c) \(\frac{21}{24}=0\dc875=87\dc5\%\). &nbsp; d) \(330:0\dc55=600\) L.")
  + P(r"e) \(54:0\dc12=450\) alumnes; \(450-54=396\) no fan arts. &nbsp; f) Queden \(320-136=184\) pàgines: \(\frac{184}{320}=0\dc575=57\dc5\,\%\).", r"e) \(54:0\dc12=450\) alumnos; \(450-54=396\) no hacen artes. &nbsp; f) Quedan \(320-136=184\) páginas: \(\frac{184}{320}=0\dc575=57\dc5\,\%\).", r"e) \(54:0\dc12=450\) students; \(450-54=396\) don't do arts. &nbsp; f) \(320-136=184\) pages are left: \(\frac{184}{320}=0\dc575=57\dc5\%\)."))
ck(Dm(18) / 72, '0.25'); ck(Dm(9) / 12, '0.75'); ck(Dm(32) / Dm('0.25'), 128); ck(Dm(21) / 24, '0.875'); ck(Dm(330) / Dm('0.55'), 600); ck(Dm(54) / Dm('0.12'), 450); ck(Dm(184) / 320, '0.575')

# ============================================================ 6.8
s8 = box('prop', L('Augments percentuals', 'Aumentos porcentuales', 'Percentage increases'),
  P(r"Un patinet costa 80 € i el preu puja un 15 %. Podem calcular el preu final de dues maneres:", r"Un patinete cuesta 80 € y el precio sube un 15 %. Podemos calcular el precio final de dos maneras:", r"A scooter costs 80 € and the price goes up 15%. We can work out the final price in two ways:")
  + ol(L(r"Calculem l'augment i el sumem: \(\ 80\cdot0\dc15=12\) €; \(\ 80+12=\boxed{92\ €}\).", r"Calculamos el aumento y lo sumamos: \(\ 80\cdot0\dc15=12\) €; \(\ 80+12=\boxed{92\ €}\).", r"Work out the increase and add it: \(\ 80\cdot0\dc15=12\) €; \(\ 80+12=\boxed{92\ €}\)."),
       L(r"Si augmenta un 15 %, ara val el \(100+15=115\,\%\) del preu inicial: \(\ 80\cdot1\dc15=\boxed{92\ €}\).", r"Si aumenta un 15 %, ahora vale el \(100+15=115\,\%\) del precio inicial: \(\ 80\cdot1\dc15=\boxed{92\ €}\).", r"If it goes up 15%, it's now worth \(100+15=115\%\) of the original price: \(\ 80\cdot1\dc15=\boxed{92\ €}\).")))
ck(80 * Dm('1.15'), 92)
s8 += box('prop', L('Disminucions percentuals', 'Disminuciones porcentuales', 'Percentage decreases'),
  P(r"Unes sabatilles de 64 € tenen un descompte del 25 %:", r"Unas zapatillas de 64 € tienen un descuento del 25 %:", r"A pair of 64 € trainers has 25% off:")
  + ol(L(r"Calculem el descompte i el restem: \(\ 64\cdot0\dc25=16\) €; \(\ 64-16=\boxed{48\ €}\).", r"Calculamos el descuento y lo restamos: \(\ 64\cdot0\dc25=16\) €; \(\ 64-16=\boxed{48\ €}\).", r"Work out the discount and subtract it: \(\ 64\cdot0\dc25=16\) €; \(\ 64-16=\boxed{48\ €}\)."),
       L(r"Si ens descompten el 25 %, paguem el \(100-25=75\,\%\): \(\ 64\cdot0\dc75=\boxed{48\ €}\).", r"Si nos descuentan el 25 %, pagamos el \(100-25=75\,\%\): \(\ 64\cdot0\dc75=\boxed{48\ €}\).", r"If we get 25% off, we pay \(100-25=75\%\): \(\ 64\cdot0\dc75=\boxed{48\ €}\).")))
ck(64 * Dm('0.75'), 48)
s8 += box('def', L('Índex de variació', 'Índice de variación', 'Multiplier'),
  P(r"El nombre pel qual multipliquem en el segon mètode s'anomena <strong>índex de variació</strong>. És el mètode més ràpid i el que funciona sempre:", r"El número por el que multiplicamos en el segundo método se llama <strong>índice de variación</strong>. Es el método más rápido y el que funciona siempre:", r"The number we multiply by in the second method is called the <strong>multiplier</strong>. It's the quickest method and it always works:")
  + table([L('Variació', 'Variación', 'Change'), L('Índex de variació', 'Índice de variación', 'Multiplier'), L('Exemples', 'Ejemplos', 'Examples')],
          [[L('Augment del \\(p\\,\\%\\)', 'Aumento del \\(p\\,\\%\\)', '\\(p\\%\\) increase'), r'\(1+\frac{p}{100}\)', r'\(+15\,\%\to1\dc15\quad +21\,\%\to1\dc21\quad +4\,\%\to1\dc04\)'],
           [L('Disminució del \\(p\\,\\%\\)', 'Disminución del \\(p\\,\\%\\)', '\\(p\\%\\) decrease'), r'\(1-\frac{p}{100}\)', r'\(-25\,\%\to0\dc75\quad -8\,\%\to0\dc92\quad -50\,\%\to0\dc5\)']])
  + r'\[\tri{Quantitat final}{Cantidad final}{Final amount}=\tri{Quantitat inicial}{Cantidad inicial}{Starting amount}\cdot\tri{índex de variació}{índice de variación}{multiplier}\]'
  + P(r"Un índex major que 1 indica un augment; menor que 1, una disminució. L'<strong>IVA</strong> (impost sobre el valor afegit) és un augment percentual: el general és del 21 %, el reduït del 10 % i el superreduït del 4 %.", r"Un índice mayor que 1 indica un aumento; menor que 1, una disminución. El <strong>IVA</strong> (impuesto sobre el valor añadido) es un aumento porcentual: el general es del 21 %, el reducido del 10 % y el superreducido del 4 %.", r"A multiplier greater than 1 means an increase; less than 1, a decrease. Spanish <strong>VAT</strong> (IVA) is a percentage increase: the standard rate is 21%, the reduced rate 10% and the super-reduced rate 4%."))
s8 += box('prop', L('Calcular la quantitat inicial i el percentatge de variació', 'Calcular la cantidad inicial y el porcentaje de variación', 'Finding the starting amount and the percentage change'),
  P(r"<strong>Quantitat inicial.</strong> Si coneixem la quantitat final, fem l'operació inversa: <strong>dividim</strong> entre l'índex de variació. Després d'una rebaixa del 25 % paguem 48 €; el preu inicial era \(48:0\dc75=\boxed{64\ €}\).",
    r"<strong>Cantidad inicial.</strong> Si conocemos la cantidad final, hacemos la operación inversa: <strong>dividimos</strong> entre el índice de variación. Después de una rebaja del 25 % pagamos 48 €; el precio inicial era \(48:0\dc75=\boxed{64\ €}\).",
    r"<strong>Starting amount.</strong> If we know the final amount, we do the inverse: <strong>divide</strong> by the multiplier. After 25% off we pay 48 €; the original price was \(48:0\dc75=\boxed{64\ €}\).")
  + note(r"<strong>No</strong> és \(48+25\,\%\ \text{de}\ 48=60\) €! El 25 % es calcula sobre el preu inicial (64 €), no sobre el final.", r"¡<strong>No</strong> es \(48+25\,\%\ \text{de}\ 48=60\) €! El 25 % se calcula sobre el precio inicial (64 €), no sobre el final.", r"It is <strong>not</strong> \(48+25\%\ \text{of}\ 48=60\) €! The 25% is worked out on the original price (64 €), not on the final one.", '⚠️')
  + P(r"<strong>Percentatge de variació.</strong> Si coneixem les dues quantitats, dividim la final entre la inicial per a obtindre l'índex, o calculem la variació respecte de la inicial. Una samarreta passa de 25 € a 21 €:",
      r"<strong>Porcentaje de variación.</strong> Si conocemos las dos cantidades, dividimos la final entre la inicial para obtener el índice, o calculamos la variación respecto de la inicial. Una camiseta pasa de 25 € a 21 €:",
      r"<strong>Percentage change.</strong> If we know both amounts, divide the final by the starting amount to get the multiplier, or work out the change relative to the starting amount. A T-shirt goes from 25 € to 21 €:")
  + r'\[\frac{21}{25}=0\dc84=1-0\dc16\ \Rightarrow\ \boxed{-16\,\%}\qquad\text{o}\qquad\frac{25-21}{25}=\frac{4}{25}=0\dc16=16\,\%\ \tri{de descompte}{de descuento}{off}\]')
ck(Dm(48) / Dm('0.75'), 64); ck(Dm(21) / 25, '0.84')
s8 += widget('w-var', '🏷️', L('Augments i disminucions', 'Aumentos y disminuciones', 'Increases and decreases'),
  f'  <div class="wrow">{gseg("t", [("+", L("Augment", "Aumento", "Increase")), ("-", L("Disminució", "Disminución", "Decrease"))], "+")}{gseg("w", [("f", L("Calcula la final", "Calcula la final", "Find the final")), ("i", L("Calcula la inicial", "Calcula la inicial", "Find the starting"))], "f")}</div>\n'
  + f'  <div class="wrow" style="margin-top:8px">{nin("q", "Quantitat", "Cantidad", "Amount", "80", "s")}{nin("p", "Percentatge (%)", "Porcentaje (%)", "Percentage (%)", "15", "s")}</div>\n'
  + '  ' + quick([('+;f;80;15', '80 € + 15 %'), ('-;f;64;25', '64 € − 25 %'), ('+;f;50;21', '50 € + IVA 21 %'), ('-;f;39,90;30', '39,90 € − 30 %'), ('-;i;48;25', '? − 25 % = 48'), ('+;i;60,50;21', '? + 21 % = 60,50'), ('+;i;2520;5', '? + 5 % = 2520')]) + '\n')
